{-| @Backend.Runtime.Host.Process — the clocks, the program's arguments and environment, the machine's directories and separators, leaving, sleeping and the system's random bytes, as `Pudu.Eval.Io`, `Pudu.Eval.Clock` and `Pudu.Eval.Entropy` answer them. -}
module Pudu.Backend.Runtime.Host.Process (hostProcessParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
hostProcessParts :: [(Text, [Text], [Text])]
hostProcessParts =
  [ ("host_clock", ["host_time", "kernel_int"],
      [ "/* Milliseconds on the clock that only moves forward. */"
      , "static pudu_int pudu_host_clock(void) {"
      , "  struct timespec now;"
      , "  (void)clock_gettime(CLOCK_MONOTONIC, &now);"
      , "  return pudu_kernel_int((int64_t)now.tv_sec * 1000 + (int64_t)((now.tv_nsec + 500000L) / 1000000L));"
      , "}"
      ])
  , ("host_clock_nanos", ["host_time", "kernel_int"],
      [ "static pudu_int pudu_host_clock_nanos(void) {"
      , "  struct timespec now;"
      , "  (void)clock_gettime(CLOCK_MONOTONIC, &now);"
      , "  return pudu_kernel_int((int64_t)now.tv_sec * INT64_C(1000000000) + (int64_t)now.tv_nsec);"
      , "}"
      ])
  , ("host_now", ["host_time", "kernel_int"],
      [ "/* Milliseconds since the start of 1970 on the system clock. */"
      , "static pudu_int pudu_host_now(void) {"
      , "  struct timespec now;"
      , "  (void)clock_gettime(CLOCK_REALTIME, &now);"
      , "  return pudu_kernel_int((int64_t)now.tv_sec * 1000 + (int64_t)((now.tv_nsec + 500000L) / 1000000L));"
      , "}"
      ])
  , ("host_zone_offset", ["host_time", "kernel_int"],
      [ "/* The local zone's minutes east of UTC. */"
      , "static pudu_int pudu_host_zone_offset(void) {"
      , "  time_t now = time(NULL);"
      , "  struct tm local;"
      , "#if defined(_WIN32)"
      , "  long seconds = 0;"
      , "  (void)localtime_s(&local, &now);"
      , "  (void)_get_timezone(&seconds);"
      , "  return pudu_kernel_int((int64_t)(-seconds / 60) + (local.tm_isdst > 0 ? 60 : 0));"
      , "#else"
      , "  (void)localtime_r(&now, &local);"
      , "  return pudu_kernel_int((int64_t)(local.tm_gmtoff / 60));"
      , "#endif"
      , "}"
      ])
  , ("host_sleep", ["host_time", "host_done", "host_gate", "kernel_signed"],
      [ "static int pudu_host_sleep(pudu_int millis) {"
      , "  int64_t wanted = pudu_kernel_signed(millis.bits);"
      , "  pudu_host_done(0);"
      , "  if (wanted > 0) {"
      , "    struct timespec left;"
      , "    left.tv_sec = (time_t)(wanted / 1000);"
      , "    left.tv_nsec = (long)(wanted % 1000) * 1000000L;"
      , "    pudu_host_leave();"
      , "    while (nanosleep(&left, &left) != 0 && errno == EINTR) {}"
      , "    pudu_host_enter();"
      , "  }"
      , "  return 1;"
      , "}"
      ])
  , ("host_arguments", ["host_optional", "array", "array_reserve", "text_copy"],
      [ "/* What the program was started with, after its own name. */"
      , "PUDU_OPTIONAL static int pudu_host_argument_count = 0;"
      , "PUDU_OPTIONAL static char **pudu_host_argument_values = NULL;"
      , "static pudu_box *pudu_host_arguments(void) {"
      , "  pudu_box *array = pudu_array_new(0);"
      , "  for (int index = 1; index < pudu_host_argument_count; ++index) {"
      , "    pudu_array_reserve(array, pudu_array_length(array) + 1);"
      , "    array->fields[0].items->cells[pudu_array_length(array)].text = pudu_text_copy(pudu_host_argument_values[index], strlen(pudu_host_argument_values[index]));"
      , "    pudu_array_length(array) += 1;"
      , "  }"
      , "  return array;"
      , "}"
      ])
  , ("host_environment", ["array", "array_reserve", "text_copy"],
      [ "#if !defined(_WIN32)"
      , "extern char **environ;"
      , "#endif"
      , "/* Every variable as a name and a value, in the order the system holds them. */"
      , "static pudu_box *pudu_host_environment(void) {"
      , "  pudu_box *array = pudu_array_new(0);"
      , "#if defined(_WIN32)"
      , "  char **entries = _environ;"
      , "#else"
      , "  char **entries = environ;"
      , "#endif"
      , "  for (; entries != NULL && *entries != NULL; ++entries) {"
      , "    const char *entry = *entries, *split = strchr(entry, '=');"
      , "    pudu_box *pair;"
      , "    if (split == NULL) continue;"
      , "    pair = pudu_box_new(2);"
      , "    pair->fields[0].text = pudu_text_copy(entry, (size_t)(split - entry));"
      , "    pair->fields[1].text = pudu_text_copy(split + 1, strlen(split + 1));"
      , "    pudu_array_reserve(array, pudu_array_length(array) + 1);"
      , "    array->fields[0].items->cells[pudu_array_length(array)].box = pair;"
      , "    pudu_array_length(array) += 1;"
      , "  }"
      , "  return array;"
      , "}"
      ])
  , ("host_temporary_path", ["text_copy"],
      [ "/* Where the machine keeps files nobody means to keep. */"
      , "static pudu_text pudu_host_temporary_path(void) {"
      , "#if defined(_WIN32)"
      , "  const char *names[] = {\"TMP\", \"TEMP\", \"USERPROFILE\"};"
      , "  const char *fallback = \"C:\\\\Windows\";"
      , "#else"
      , "  const char *names[] = {\"TMPDIR\"};"
      , "  const char *fallback = \"/tmp\";"
      , "#endif"
      , "  for (size_t index = 0; index < sizeof names / sizeof names[0]; ++index) {"
      , "    const char *found = getenv(names[index]);"
      , "    if (found != NULL && found[0] != 0) return pudu_text_copy(found, strlen(found));"
      , "  }"
      , "  return pudu_text_copy(fallback, strlen(fallback));"
      , "}"
      ])
  , ("host_user_home", ["host_done", "text_copy"],
      [ "static pudu_text pudu_host_user_home(void) {"
      , "  const char *home = getenv(\"HOME\");"
      , "  if (home == NULL) home = getenv(\"USERPROFILE\");"
      , "  pudu_host_done(home == NULL ? 2 : 0);"
      , "  return home == NULL ? (pudu_text){(const unsigned char *)\"\", 0, NULL} : pudu_text_copy(home, strlen(home));"
      , "}"
      ])
  , ("host_path_separators", ["array", "array_reserve", "text_literal"],
      [ "/* The separator to write first, then the others the machine reads. */"
      , "static pudu_box *pudu_host_path_separators(void) {"
      , "#if defined(_WIN32)"
      , "  pudu_box *array = pudu_array_new(2);"
      , "  array->fields[0].items->cells[0].text = pudu_text_literal(\"\\\\\", 1);"
      , "  array->fields[0].items->cells[1].text = pudu_text_literal(\"/\", 1);"
      , "  pudu_array_length(array) = 2;"
      , "#else"
      , "  pudu_box *array = pudu_array_new(1);"
      , "  array->fields[0].items->cells[0].text = pudu_text_literal(\"/\", 1);"
      , "  pudu_array_length(array) = 1;"
      , "#endif"
      , "  return array;"
      , "}"
      ])
  , ("host_search_separator", ["text_literal"],
      [ "static pudu_text pudu_host_search_separator(void) {"
      , "#if defined(_WIN32)"
      , "  return pudu_text_literal(\";\", 1);"
      , "#else"
      , "  return pudu_text_literal(\":\", 1);"
      , "#endif"
      , "}"
      ])
  , ("host_exit", ["kernel_signed"],
      [ "/* Zero leaves in success; anything else is held to what a status carries. */"
      , "static int pudu_host_exit(pudu_int status) {"
      , "  int64_t wanted = pudu_kernel_signed(status.bits);"
      , "  fflush(stdout);"
      , "  fflush(stderr);"
      , "  exit(wanted == 0 ? 0 : (int)(wanted < 1 ? 1 : wanted > 255 ? 255 : wanted));"
      , "}"
      ])
  , ("host_secure_bytes", ["host_done", "host_fail", "host_fail_io", "kernel_signed", "kernel_fresh", "bytes_wrap"],
      [ "#if defined(__APPLE__) || defined(__FreeBSD__) || defined(__OpenBSD__) || defined(__NetBSD__)"
      , "#include <sys/random.h>"
      , "#elif defined(__linux__)"
      , "#include <sys/random.h>"
      , "#endif"
      , "static pudu_box *pudu_host_secure_bytes(pudu_int count) {"
      , "  int64_t wanted = pudu_kernel_signed(count.bits);"
      , "  unsigned char *bytes;"
      , "  pudu_text fresh;"
      , "  if (wanted < 0) { pudu_host_fail(\"the secure byte count cannot be negative\"); return NULL; }"
      , "  if (wanted > 1048576) { pudu_host_fail(\"the secure byte count cannot exceed 1048576\"); return NULL; }"
      , "  fresh = pudu_kernel_fresh((size_t)wanted, &bytes);"
      , "  for (size_t filled = 0; filled < (size_t)wanted;) {"
      , "    size_t piece = (size_t)wanted - filled > 256 ? 256 : (size_t)wanted - filled;"
      , "#if defined(_WIN32)"
      , "    for (size_t index = 0; index < piece; ++index) { unsigned int word; if (rand_s(&word) != 0) { pudu_text_release(fresh); pudu_host_fail(\"the system offered no random bytes\"); return NULL; } bytes[filled + index] = (unsigned char)word; }"
      , "#else"
      , "    if (getentropy(bytes + filled, piece) != 0) {"
      , "      pudu_text none = {(const unsigned char *)\"\", 0, NULL};"
      , "      int code = errno;"
      , "      pudu_text_release(fresh);"
      , "      pudu_host_fail_io(none, \"getentropy\", code);"
      , "      return NULL;"
      , "    }"
      , "#endif"
      , "    filled += piece;"
      , "  }"
      , "  pudu_host_done(0);"
      , "  return pudu_bytes_wrap(fresh);"
      , "}"
      ])
  ]
